WITH RECURSIVE suite(n) AS (
  SELECT 1
  UNION ALL
  SELECT n + 1 FROM suite WHERE n <= 5
)
SELECT n FROM suite;

exercises.solution:
WITH RECURSIVE suite(n) AS (
  SELECT 1
  UNION ALL
  SELECT n + 1 FROM suite WHERE n < 5
)
SELECT n FROM suite;
